fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    // If maxsplit is 0, return each string as a single-element vector (no splitting)
    if maxsplit == 0 {
        return a.into_iter()
            .map(|s| vec![s])
            .collect();
    }
    
    // For maxsplit > 0, perform right-split at most maxsplit times using sep
    // For each string, use rsplitn(maxsplit+1, &sep) so at most maxsplit splits -> maxsplit+1 parts
    a.into_iter()
        .map(|s| {
            // If s is empty, return vec with empty string as per spec
            if s.is_empty() {
                vec![String::new()]
            } else {
                // rsplitn returns iterator from right to left,
                // collect into Vec, reverse to preserve original order of parts
                let parts: Vec<String> = s.rsplitn((maxsplit as usize) + 1, &sep).map(|p| p.to_string()).collect();
                let mut parts_reversed = parts;
                parts_reversed.reverse();
                parts_reversed
            }
        })
        .collect()
}